    38  static int
    39  parse_x509_cert(sc_context_t *ctx, struct sc_pkcs15_der *der, struct sc_pkcs15_cert *cert)
    40  {
    41          int r;
    42          struct sc_algorithm_id sig_alg;
    43          struct sc_pkcs15_pubkey *pubkey = NULL;
    44          unsigned char *serial = NULL, *issuer = NULL, *subject = NULL, *buf =  der->value;
    45          size_t serial_len = 0, issuer_len = 0, subject_len = 0, data_len = 0, buflen = der->len;
    46          struct sc_asn1_entry asn1_version[] = {
    47                  { "version", SC_ASN1_INTEGER, SC_ASN1_TAG_INTEGER, 0, &cert->version, NULL },
    48                  { NULL, 0, 0, 0, NULL, NULL }
    49          };
    50          struct sc_asn1_entry asn1_extensions[] = {
    51                  { "x509v3",             SC_ASN1_OCTET_STRING,    SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, SC_ASN1_OPTIONAL| SC_ASN1_ALLOC, &cert->extensions, &cert->extensions_len },
    52                  { NULL, 0, 0, 0, NULL, NULL }
    53          };
    54          struct sc_asn1_entry asn1_tbscert[] = {
    55                  { "version",            SC_ASN1_STRUCT,    SC_ASN1_CTX | 0 | SC_ASN1_CONS, SC_ASN1_OPTIONAL, asn1_version, NULL },
    56                  { "serialNumber",       SC_ASN1_OCTET_STRING, SC_ASN1_TAG_INTEGER, SC_ASN1_ALLOC, &serial, &serial_len },
    57                  { "signature",          SC_ASN1_STRUCT,    SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, NULL, NULL },
    58                  { "issuer",             SC_ASN1_OCTET_STRING, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, SC_ASN1_ALLOC, &issuer, &issuer_len },
    59                  { "validity",           SC_ASN1_STRUCT,    SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, NULL, NULL },
    60                  { "subject",            SC_ASN1_OCTET_STRING, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, SC_ASN1_ALLOC, &subject, &subject_len },
    61                  /* Use a callback to get the algorithm, parameters and pubkey into sc_pkcs15_pubkey */
    62                  { "subjectPublicKeyInfo",SC_ASN1_CALLBACK, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, sc_pkcs15_pubkey_from_spki_fields,  &pubkey },
    63                  { "extensions",         SC_ASN1_STRUCT,    SC_ASN1_CTX | 3 | SC_ASN1_CONS, SC_ASN1_OPTIONAL, asn1_extensions, NULL },
    64                  { NULL, 0, 0, 0, NULL, NULL }
    65          };
    66          struct sc_asn1_entry asn1_cert[] = {
    67                  { "tbsCertificate",     SC_ASN1_STRUCT,    SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, asn1_tbscert, NULL },
    68                  { "signatureAlgorithm", SC_ASN1_ALGORITHM_ID, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, &sig_alg, NULL },
    69                  { "signatureValue",     SC_ASN1_BIT_STRING, SC_ASN1_TAG_BIT_STRING, 0, NULL, NULL },
    70                  { NULL, 0, 0, 0, NULL, NULL }
    71          };
    72          struct sc_asn1_entry asn1_serial_number[] = {
    73                  { "serialNumber", SC_ASN1_OCTET_STRING, SC_ASN1_TAG_INTEGER, SC_ASN1_ALLOC, NULL, NULL },
    74                  { NULL, 0, 0, 0, NULL, NULL }
    75          };
    76          struct sc_asn1_entry asn1_subject[] = {
    77                  { "subject", SC_ASN1_OCTET_STRING, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, SC_ASN1_ALLOC, NULL, NULL },
    78                  { NULL, 0, 0, 0, NULL, NULL }
    79          };
    80          struct sc_asn1_entry asn1_issuer[] = {
    81                  { "issuer", SC_ASN1_OCTET_STRING, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, SC_ASN1_ALLOC, NULL, NULL },
    82                  { NULL, 0, 0, 0, NULL, NULL }
    83          };
    84
    85          const u8 *obj;
    86          size_t objlen;
    87
    88          LOG_FUNC_CALLED(ctx);
    89
    90          memset(cert, 0, sizeof(*cert));
    91          obj = sc_asn1_verify_tag(ctx, buf, buflen, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, &objlen);
    92          if (obj == NULL)
    93                  LOG_TEST_RET(ctx, SC_ERROR_INVALID_ASN1_OBJECT, "X.509 certificate not found");
    94
    95          data_len = objlen + (obj - buf);
    96          cert->data.value = malloc(data_len);
    97          if (!cert->data.value)
    98                  LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
    99          memcpy(cert->data.value, buf, data_len);
   100          cert->data.len = data_len;
   101
   102          r = sc_asn1_decode(ctx, asn1_cert, obj, objlen, NULL, NULL);
   103          cert->key = pubkey;
   104          cert->version++;
   105
   106          LOG_TEST_GOTO_ERR(ctx, r, "ASN.1 parsing of certificate failed");
   107
   108          if (!pubkey)
   109                  LOG_TEST_GOTO_ERR(ctx, SC_ERROR_INVALID_ASN1_OBJECT, "Unable to decode subjectPublicKeyInfo from cert");
   110
   111
   112          if (serial && serial_len)   {
   113                  sc_format_asn1_entry(asn1_serial_number + 0, serial, &serial_len, 1);
   114                  r = sc_asn1_encode(ctx, asn1_serial_number, &cert->serial, &cert->serial_len);
   115                  LOG_TEST_GOTO_ERR(ctx, r, "ASN.1 encoding of serial failed");
   116          }
   117
   118          if (subject && subject_len)   {
   119                  sc_format_asn1_entry(asn1_subject + 0, subject, &subject_len, 1);
   120                  r = sc_asn1_encode(ctx, asn1_subject, &cert->subject, &cert->subject_len);
   121                  LOG_TEST_GOTO_ERR(ctx, r, "ASN.1 encoding of subject");
   122          }
   123
   124          if (issuer && issuer_len)   {
   125                  sc_format_asn1_entry(asn1_issuer + 0, issuer, &issuer_len, 1);
   126                  r = sc_asn1_encode(ctx, asn1_issuer, &cert->issuer, &cert->issuer_len);
   127                  LOG_TEST_GOTO_ERR(ctx, r, "ASN.1 encoding of issuer");
   128          }
   129
   130  err:
   131          /* not used for anything */
   132          sc_asn1_clear_algorithm_id(&sig_alg);
   133          free(serial);
   134          free(subject);
   135          free(issuer);
   136
   137          LOG_FUNC_RETURN(ctx, r);
   138  }
