   153   * if *name is NULL, sc_pkcs15_get_name_from_dn will allocate space for name.
   154   */
   155  int
   156  sc_pkcs15_get_name_from_dn(struct sc_context *ctx, const u8 *dn, size_t dn_len,
   157          const struct sc_object_id *type, u8 **name, size_t *name_len)
   158  {
   159          const u8 *rdn = NULL;
   160          const u8 *next_ava = NULL;
   450                                  asn1_x509_cert_attr[2], asn1_type_cert_attr[2],
   451                                  asn1_cert[2], asn1_x509_cert_value_choice[3];
   452          struct sc_asn1_pkcs15_object cert_obj = {
   453                  obj, asn1_com_cert_attr, NULL,
   454                  asn1_type_cert_attr };
   455          sc_pkcs15_der_t *der = &info.value;
   456          u8 id_value[128];
   457          int id_type;
   458          size_t id_value_len = sizeof(id_value);
   459          int r;
   460
   461          sc_copy_asn1_entry(c_asn1_cred_ident, asn1_cred_ident);
   462          sc_copy_asn1_entry(c_asn1_com_cert_attr, asn1_com_cert_attr);
   463          sc_copy_asn1_entry(c_asn1_x509_cert_attr, asn1_x509_cert_attr);
   464          sc_copy_asn1_entry(c_asn1_x509_cert_value_choice, asn1_x509_cert_value_choice);
   465          sc_copy_asn1_entry(c_asn1_type_cert_attr, asn1_type_cert_attr);
   466          sc_copy_asn1_entry(c_asn1_cert, asn1_cert);
   467
   468          sc_format_asn1_entry(asn1_cred_ident + 0, &id_type, NULL, 0);
   469          sc_format_asn1_entry(asn1_cred_ident + 1, &id_value, &id_value_len, 0);
   470          sc_format_asn1_entry(asn1_com_cert_attr + 0, &info.id, NULL, 0);
   471          sc_format_asn1_entry(asn1_com_cert_attr + 1, &info.authority, NULL, 0);
   472          sc_format_asn1_entry(asn1_com_cert_attr + 2, asn1_cred_ident, NULL, 0);
   473          sc_format_asn1_entry(asn1_x509_cert_attr + 0, asn1_x509_cert_value_choice, NULL, 0);
   474          sc_format_asn1_entry(asn1_x509_cert_value_choice + 0, &info.path, NULL, 0);
   475          sc_format_asn1_entry(asn1_x509_cert_value_choice + 1, &der->value, &der->len, 0);
   476          sc_format_asn1_entry(asn1_type_cert_attr + 0, asn1_x509_cert_attr, NULL, 0);
   477          sc_format_asn1_entry(asn1_cert + 0, &cert_obj, NULL, 0);
   478
   479          /* Fill in defaults */
   480          memset(&info, 0, sizeof(info));
   481          info.authority = 0;
   482
   483          r = sc_asn1_decode(ctx, asn1_cert, *buf, *buflen, buf, buflen);
   484          /* In case of error, trash the cert value (direct coding) */
   485          if (r < 0 && der->value)
   486                  free(der->value);
   487          if (r == SC_ERROR_ASN1_END_OF_CONTENTS)
   488                  return r;
   489          LOG_TEST_RET(ctx, r, "ASN.1 decoding failed");
   490
   491          if (!p15card->app || !p15card->app->ddo.aid.len) {
   492                  if (!p15card->file_app) {
   493                          free(der->value);
   494                          return SC_ERROR_INTERNAL;
   495                  }
   496                  r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &info.path);
   497                  LOG_TEST_RET(ctx, r, "Cannot make absolute path");
   498          }
   499          else   {
   500                  info.path.aid = p15card->app->ddo.aid;
   501          }
   502          sc_log(ctx, "Certificate path '%s'", sc_print_path(&info.path));
   503
   504          switch (p15card->opts.private_certificate) {
   505                  case SC_PKCS15_CARD_OPTS_PRIV_CERT_DECLASSIFY:
   506                          sc_log(ctx, "Declassifying certificate");
   507                          obj->flags &= ~SC_PKCS15_CO_FLAG_PRIVATE;
   508                          break;
   509                  case SC_PKCS15_CARD_OPTS_PRIV_CERT_IGNORE:
   510                          sc_log(ctx, "Ignoring certificate");
   511                          free(der->value);
   512                          return 0;
   513          }
   514
   515          obj->type = SC_PKCS15_TYPE_CERT_X509;
   516          obj->data = malloc(sizeof(info));
   517          if (obj->data == NULL)
   518                  LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
